-- =====================================================================
-- Import de Imagenes de OT (legacy o_trabajo.imagen1..imagen6)
--
-- 1051 OT con al menos 1 imagen referenciada (5568 referencias en
-- total, hasta 6 por OT). Carpeta COPIA_IMG/ot_img provista por el
-- usuario 2026-08-27 (6050 archivos, copiada completa a
-- backend/uploads/ot-imagenes/, gitignored -- mismo criterio que el
-- resto de uploads/).
--
-- 5414/5568 referencias (97.2%) matchean un archivo real en la carpeta
-- por nombre exacto. Las 154 restantes son todas de un mismo patron
-- raro de la legacy -- el valor guardado en imagen1..6 trae un prefijo
-- "YYYY-MM-DD-HH:MM:SS-" pegado adelante del nombre real (ej.
-- "2018-05-23-09:55:35-20171020_172047.jpg"), y NI el string completo
-- NI el sufijo sin ese prefijo existen como archivo en la carpeta
-- provista -- se probaron ambas formas, no matchea ninguna. No se
-- inventa el archivo, esas referencias se excluyen (igual criterio que
-- layout/pautas de OF cuando no habia carpeta).
--
-- ot_id resuelto contra ingenieria.ordenes_trabajo por numero_ot=id_ot
-- (mismo lookup que despiece_ot). orden = posicion original en
-- imagen1..6 (0-5), preserva el orden aunque algun slot intermedio se
-- haya excluido por no tener archivo.
-- =====================================================================

INSERT INTO ingenieria.ot_imagenes (ot_id, url, orden)
